  (8785, 18, 14, 'MV', 'Innerstädtische Grünflächen, Kleingärten und Kaltluftschneisen gezielt fördern, um sommerlicher Überhitzung vorzubeugen.', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=33', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8786, 18, 14, 'MV', 'Hochwasser- und Küstenschutzprogramme fortsetzen und regelmäßig überprüfen; naturnahe und technische Maßnahmen nach Wirksamkeit kombinieren.', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=35', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8787, 18, 14, 'MV', 'Bestehende Retentionsräume sichern, wo sie für nachgewiesenen Hochwasserschutz erforderlich sind.', '{1805}', null, 1, 3, null, 'Bestehende Retentionsräume zu sichern erhält ihre dämpfende Wirkung auf Hochwasser. Dagegen: nur Bestand und nur bei nachgewiesenem Bedarf, neue Rückhalteräume entstehen nicht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=35', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-08', false, true, 'blind'),
