  (8789, 18, 15, 'BE', 'Verpflichtende Entsiegelung, wo mit geringem Aufwand möglich, und Flächensparprogramme; Anreize für private Eigentümer zur Teilentsiegelung', '{1804}', 8737, 2, 3, null, 'Entsiegelte Flächen verringern Oberflächenabfluss (je nach Belag bis 40 bis 80 %) und Hitze; ein Fonds ist im Landeshaushalt umsetzbar. Dagegen: Private beteiligen sich oft wenig, der Umfang bleibt begrenzt.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=80', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8790, 18, 15, 'BE', 'Jeder gefällte Baum in Berlin wird nachgepflanzt; Nachpflanzpflicht konsequenter durchsetzen und per Baumbilanz kontrollieren', '{1803}', null, 1, 3, null, 'Eine durchgesetzte Nachpflanzpflicht verhindert, dass der Baumbestand schrumpft, und ist rechtlich einfach. Dagegen: junge Ersatzbäume kühlen lange deutlich weniger als gefällte alte Bäume.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=79', null, 'offen', '2026-10-08', false, true, 'blind'),
