  (8792, 18, 15, 'ST', 'Mehr Überflutungsflächen schaffen, Versiegelungen und Einengungen entlang der Flussläufe abbauen und laufende Hochwasserschutzmaßnahmen zügig vollenden.', '{1805}', 8741, 2, 2, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich und entlasten Orte flussabwärts. Dagegen: Flächenerwerb und Planung dauern oft länger als eine Wahlperiode.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=205', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8793, 18, 16, 'BE', 'Verbindlicher Mindestanteil an Grünflächen bei allen Neubauvorhaben (Biotopflächenfaktor), gegen Hitze und für bessere Regenversickerung.', '{1803,1804}', 8739, 1, 3, null, 'Gründächer und Grünflächen halten Regen zurück und kühlen; per Bauordnung umsetzbar. Dagegen: gilt nur für Neubauten, die jährlich einen kleinen Teil des Bestands ausmachen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=202', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8794, 18, 16, 'BE', 'Netto-Null-Versiegelung bis 2030: Wo versiegelt wird, wird in gleicher Größe entsiegelt; Entsiegelungsprogramm umsetzen.', '{1804}', null, 2, 2, null, 'Eine Ausgleichspflicht für neue Versiegelung stoppt den Zuwachs versiegelter Flächen direkt. Dagegen: kaum erprobt, Entsiegelungsflächen und Mittel bis 2030 sind ungewiss.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=202', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8795, 18, 16, 'BE', 'Schwammstadt durch Entsiegelung, Regenwassermanagement und Versickerung vor Ort, auch im Liegenschaftsbestand.', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=204', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8796, 18, 16, 'BE', 'In sozial benachteiligten Kiezen Hitzeschutz und mehr Grünflächen und Stadtbäume konsequent umsetzen, auf Grundlage des Umweltgerechtigkeitsatlas.', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=201', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8797, 18, 16, 'MV', 'Flächensparziele und Flächenkontingente in der Raumordnung einführen, um den Flächenverbrauch zu begrenzen.', '{1804}', null, 2, 2, null, 'Verbindliche Flächenkontingente begrenzten im Modellversuch die Neuinanspruchnahme zuverlässig und sind in der Landesplanung möglich. Dagegen: nur im Planspiel erprobt, bestehende Versiegelung bleibt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=22', 'https://www.umweltbundesamt.de/node/61839', 'offen', '2026-10-08', false, true, 'blind'),
