  (8799, 18, 16, 'ST', 'Schwammstadtprinzip in Kommunen verankern und bei neuen Projekten sowie Sanierungen anwenden.', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8800, 18, 16, 'ST', 'Regenrückhalt systematisch stärken, damit Wasser in der Fläche bleibt.', '{1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8801, 18, 17, 'BE', 'Baumoffensiven mit verlässlicher Haushaltsfinanzierung und Priorität für Neupflanzungen und Pflege, um die Hitze zu senken.', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8802, 18, 17, 'BE', 'Verbindliche Begrünungspflichten für Neubauten: begrünte Dächer, Fassaden und Innenhöfe als Regel.', '{1803}', 8739, 1, 3, null, 'Gründächer und Grünflächen halten Regen zurück und kühlen; per Bauordnung umsetzbar. Dagegen: gilt nur für Neubauten, die jährlich einen kleinen Teil des Bestands ausmachen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8803, 18, 17, 'BE', 'Asphaltflächen entsiegeln, damit Regenwasser versickern kann und Schatten entsteht.', '{1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8804, 18, 17, 'BE', 'Schwammstadt-Prinzip als Leitlinie aller Planungen: Regenwasser vor Ort versickern, speichern oder nutzen statt in die Kanalisation leiten.', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8805, 18, 17, 'MV', 'Ausbau einer leistungsfähigen Regenwasserinfrastruktur, bezogen auf Einträge in Gewässer.', '{1804}', null, 1, 2, null, 'Mehr Regenwasserinfrastruktur entlastet Gewässer von Einträgen. Dagegen: Ziel ist Gewässerschutz, nicht Überflutungsschutz; an Versiegelung und Versickerung ändert sich kaum etwas.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=85', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8806, 18, 17, 'ST', 'Städte und Gemeinden klimaangepasst umbauen: entsiegeln, mehr Grünflächen, Schwammstadt, Grünfassaden und Schattenräume gegen Hitze und Starkregen', '{1803,1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=29', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8807, 18, 17, 'ST', 'Regenwasser in Siedlungen gezielt versickern lassen statt nur abzuleiten; Schwammstadt mit Rückhalt, Versickerung und Verdunstung', '{1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8808, 18, 17, 'ST', 'Deichrückverlegungen und Auenrenaturierung, um Überschwemmungsflächen zurückzugewinnen', '{1805}', 8741, 2, 2, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich und entlasten Orte flussabwärts. Dagegen: Flächenerwerb und Planung dauern oft länger als eine Wahlperiode.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8809, 18, 17, 'ST', 'Baurecht so gestalten, dass in hochwassergefährdeten Zonen keine neuen Baugebiete entstehen', '{1805}', 8742, 2, 2, null, 'Bauverzicht in Überschwemmungsflächen gilt als wirksamste Vermeidung neuer Schäden. Dagegen: schützt bestehende Gebäude nicht; das Wasserhaushaltsgesetz verbietet vieles schon, Verschärfungen brauchen Landesrecht und Raumordnung.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.lfu.bayern.de/wasser/hw_handlungsfelder/vermeidung/index.htm', 'belegt', '2026-10-08', false, true, 'blind'),
  (8810, 18, 17, 'ST', 'Bestehende Hochwasserschutzanlagen modernisieren und an das veränderte Klima anpassen', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8811, 18, 18, 'BE', 'Regenwasser vor Ort speichern, versiegelte Flächen auf Plätzen und Straßen durch sickerfähige Böden ersetzen (Entsiegelungsoffensive), Genehmigung von Dach- und Fassadenbegrünung vereinfachen.', '{1803,1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=97', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8812, 18, 18, 'BE', 'Hitze-Aktionsplan mit Koordination und Finanzierung ausbauen, mehr Straßenbäume pflanzen für schattige Aufenthaltsorte.', '{1803}', 8733, 2, 3, null, 'Grün, Verschattung und baulicher Hitzeschutz senken die Hitzebelastung nachweislich; ein Landesprogramm ist im Haushalt umsetzbar. Dagegen: Wirkung hängt von Mitteln und Umsetzung in den Kommunen ab.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=97', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8813, 18, 18, 'BE', 'Baurecht anpassen, damit Hitzeschutz an Gebäuden wie Begrünung und Verschattung unbürokratisch möglich wird.', '{1803}', null, 1, 3, null, 'Einfachere Genehmigung baut Hürden für Begrünung und Verschattung ab und ist per Landesbauordnung schnell möglich. Dagegen: ob dadurch tatsächlich mehr umgesetzt wird, ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=95', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8814, 18, 18, 'BE', 'Bei der Umgestaltung der Kieze Entsiegelung, Begrünung und Regenwassermanagement umsetzen, um sie gegen Hitze und Starkregen widerstandsfähiger zu machen.', '{1803,1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=35', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8815, 18, 18, 'MV', 'Deiche an der Ostseeküste gezielt umbauen, sodass sie Hochwasserschutz mit Radwegen und Naherholung verbinden.', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=41', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8816, 18, 18, 'ST', 'Baumpflanzprogramme in Städten und Dörfern zur Verschattung von Straßen, Plätzen und Schulwegen', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=179', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8817, 18, 18, 'ST', 'Landesweiter Entsiegelungsfonds für Kommunen zur Förderung von Rückbauprojekten', '{1804}', 8737, 2, 3, null, 'Entsiegelte Flächen verringern Oberflächenabfluss (je nach Belag bis 40 bis 80 %) und Hitze; ein Fonds ist im Landeshaushalt umsetzbar. Dagegen: Private beteiligen sich oft wenig, der Umfang bleibt begrenzt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=73', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8818, 18, 18, 'ST', 'Schulen, Kitas und Pflegeheime mit Kühlsystemen ausstatten', '{1803}', null, 2, 2, null, 'Kühlung in Innenräumen senkt das Hitzesterberisiko nachweislich und schützt Kinder und Pflegebedürftige direkt. Dagegen: hohe Investitionen für viele Gebäude, die Stadt selbst wird nicht kühler.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=77', 'https://spiral.imperial.ac.uk/entities/publication/84293dd2-cc76-4eec-abe8-2389e528665f', 'belegt', '2026-10-08', false, true, 'blind'),
  (8819, 18, 18, 'ST', 'Mehr Überflutungsflächen und natürliche Rückhalteräume für Hochwasser aufbauen', '{1805}', 8741, 2, 2, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich und entlasten Orte flussabwärts. Dagegen: Flächenerwerb und Planung dauern oft länger als eine Wahlperiode.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=180', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8820, 18, 18, 'ST', 'Kanalisationen digital steuerbar machen, um Starkregen abzufedern', '{1804}', null, 1, 2, null, 'Gesteuerte Kanalnetze nutzen vorhandenen Stauraum besser und können Überläufe verringern. Dagegen: Wirkung bei extremem Starkregen begrenzt, an der Versiegelung ändert sich nichts.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=180', null, 'offen', '2026-10-08', false, true, 'blind');

